values
    ('20000000-0000-4000-8000-000000000001'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'SEN_COMPLETE', 'Oraciones completas', 'Distinguir cláusulas completas de fragmentos y estructuras sin sujeto o verbo principal.', 'A2', 1, true),
    ('20000000-0000-4000-8000-000000000002'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'SEN_WORD_ORDER', 'Orden de palabras', 'Controlar el orden canónico y las posiciones de sujeto, verbo, objeto y adverbios.', 'A2', 2, true),
    ('20000000-0000-4000-8000-000000000003'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'SEN_EXPLETIVE', 'Sujetos formales it/there', 'Usar correctamente it y there como sujetos formales y concordar con el sujeto lógico.', 'B1', 3, true),
    ('20000000-0000-4000-8000-000000000004'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'SEN_INVERSION', 'Inversión', 'Aplicar inversión tras expresiones negativas, restrictivas y condicionales formales.', 'B2', 4, true),
    ('20000000-0000-4000-8000-000000000005'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'SEN_BOUNDARY', 'Límites y conexión de oraciones', 'Evitar fragmentos, run-ons y comma splices mediante coordinación y subordinación correctas.', 'B1', 5, true),
    ('20000000-0000-4000-8000-000000000006'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_AGREEMENT', 'Concordancia sujeto-verbo', 'Hacer concordar el verbo con el núcleo real del sujeto en estructuras simples y complejas.', 'A2', 1, true),
    ('20000000-0000-4000-8000-000000000007'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_TENSE', 'Tiempos verbales', 'Seleccionar tiempos verbales coherentes con relaciones temporales explícitas e implícitas.', 'B1', 2, true),
    ('20000000-0000-4000-8000-000000000008'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_ASPECT', 'Aspecto y duración', 'Expresar continuidad, resultado y duración con formas perfectas y progresivas.', 'B1', 3, true),
    ('20000000-0000-4000-8000-000000000009'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_VOICE', 'Voz activa y pasiva', 'Formar la voz pasiva y elegirla según el foco informativo y la agencia.', 'A2', 4, true),
    ('20000000-0000-4000-8000-000000000010'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_MODAL', 'Modales', 'Expresar posibilidad, obligación, deducción y capacidad con modales y formas perfectas.', 'B1', 5, true),
    ('20000000-0000-4000-8000-000000000011'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_SUBJUNCTIVE', 'Subjuntivo y formas irreales', 'Usar el subjuntivo mandativo y las formas verbales de condiciones o deseos irreales.', 'B2', 6, true),
    ('20000000-0000-4000-8000-000000000012'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_COMPLEMENT', 'Complementos verbales', 'Elegir gerundio, infinitivo o cláusula según el patrón exigido por el verbo.', 'B1', 7, true),
    ('20000000-0000-4000-8000-000000000013'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'VERB_TRANSITIVITY', 'Transitividad y objetos', 'Usar objetos y complementos requeridos por verbos transitivos, intransitivos y ditransitivos.', 'B1', 8, true),
    ('20000000-0000-4000-8000-000000000014'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'CLAUSE_NOUN', 'Cláusulas nominales', 'Construir cláusulas nominales como sujeto, objeto o complemento con orden declarativo.', 'B1', 1, true),
    ('20000000-0000-4000-8000-000000000015'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'CLAUSE_RELATIVE', 'Cláusulas relativas', 'Seleccionar pronombres relativos y construir cláusulas restrictivas y explicativas.', 'B1', 2, true),
    ('20000000-0000-4000-8000-000000000016'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'CLAUSE_ADVERB', 'Cláusulas adverbiales', 'Relacionar tiempo, causa, concesión, condición y propósito mediante subordinación.', 'B1', 3, true),
    ('20000000-0000-4000-8000-000000000017'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'CLAUSE_REDUCED_REL', 'Relativas reducidas', 'Reducir cláusulas relativas activas y pasivas sin perder la relación con el sustantivo.', 'B2', 4, true),
    ('20000000-0000-4000-8000-000000000018'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'CLAUSE_REDUCED_ADV', 'Adverbiales reducidas', 'Reducir cláusulas adverbiales cuando comparten sujeto con la cláusula principal.', 'B2', 5, true),
    ('20000000-0000-4000-8000-000000000019'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'CLAUSE_PARTICIPIAL', 'Frases participiales', 'Relacionar correctamente frases participiales con su sujeto y secuencia temporal.', 'B2', 6, true),
    ('20000000-0000-4000-8000-000000000020'::uuid, '10000000-0000-4000-8000-000000000004'::uuid, 'NOUN_NUMBER', 'Número y contabilidad', 'Distinguir sustantivos contables, incontables y plurales irregulares.', 'A2', 1, true),
    ('20000000-0000-4000-8000-000000000021'::uuid, '10000000-0000-4000-8000-000000000004'::uuid, 'NOUN_ARTICLE', 'Artículos', 'Elegir a, an, the o artículo cero según referencia, especificidad y sonido inicial.', 'A2', 2, true),
    ('20000000-0000-4000-8000-000000000022'::uuid, '10000000-0000-4000-8000-000000000004'::uuid, 'NOUN_QUANTIFIER', 'Cuantificadores', 'Combinar cuantificadores con nombres contables o incontables y expresar cantidad con precisión.', 'A2', 3, true),
    ('20000000-0000-4000-8000-000000000023'::uuid, '10000000-0000-4000-8000-000000000004'::uuid, 'NOUN_PRONOUN', 'Pronombres y referencia', 'Mantener concordancia, caso y referencia clara en pronombres personales, relativos y reflexivos.', 'A2', 4, true),
    ('20000000-0000-4000-8000-000000000024'::uuid, '10000000-0000-4000-8000-000000000004'::uuid, 'NOUN_APPOSITION', 'Aposición', 'Usar grupos nominales apositivos para identificar o explicar otro sustantivo.', 'B1', 5, true),
    ('20000000-0000-4000-8000-000000000025'::uuid, '10000000-0000-4000-8000-000000000005'::uuid, 'MOD_ADJ_ADV', 'Adjetivos y adverbios', 'Elegir formas adjetivales o adverbiales según la función que cumplen.', 'A2', 1, true),
    ('20000000-0000-4000-8000-000000000026'::uuid, '10000000-0000-4000-8000-000000000005'::uuid, 'MOD_ORDER', 'Orden de modificadores', 'Colocar adjetivos, adverbios y modificadores nominales en un orden natural y no ambiguo.', 'B1', 2, true),
    ('20000000-0000-4000-8000-000000000027'::uuid, '10000000-0000-4000-8000-000000000005'::uuid, 'MOD_COMPARISON', 'Comparativos y superlativos', 'Formar comparaciones, superlativos y estructuras proporcionales sin redundancia.', 'A2', 3, true),
    ('20000000-0000-4000-8000-000000000028'::uuid, '10000000-0000-4000-8000-000000000005'::uuid, 'MOD_ATTACHMENT', 'Referencia de modificadores', 'Vincular modificadores con el elemento correcto y evitar ambigüedad o modificadores colgantes.', 'B2', 4, true),
    ('20000000-0000-4000-8000-000000000029'::uuid, '10000000-0000-4000-8000-000000000006'::uuid, 'LEX_WORD_FORM', 'Familias de palabras', 'Seleccionar la categoría morfológica correcta dentro de una familia léxica.', 'B1', 1, true),
    ('20000000-0000-4000-8000-000000000030'::uuid, '10000000-0000-4000-8000-000000000006'::uuid, 'LEX_PREPOSITION', 'Preposiciones', 'Elegir preposiciones requeridas por tiempo, lugar y regímenes léxicos frecuentes.', 'A2', 2, true),
    ('20000000-0000-4000-8000-000000000031'::uuid, '10000000-0000-4000-8000-000000000006'::uuid, 'LEX_COLLOCATION', 'Colocaciones académicas', 'Reconocer combinaciones léxicas frecuentes en inglés académico.', 'B1', 3, true),
    ('20000000-0000-4000-8000-000000000032'::uuid, '10000000-0000-4000-8000-000000000006'::uuid, 'LEX_IDIOM', 'Estructuras idiomáticas', 'Usar expresiones fijas y patrones idiomáticos frecuentes en prosa formal.', 'B2', 4, true),
    ('20000000-0000-4000-8000-000000000033'::uuid, '10000000-0000-4000-8000-000000000007'::uuid, 'LOGIC_PARALLEL', 'Paralelismo', 'Mantener formas gramaticales equivalentes en listas, comparaciones y coordinaciones.', 'B1', 1, true),
    ('20000000-0000-4000-8000-000000000034'::uuid, '10000000-0000-4000-8000-000000000007'::uuid, 'LOGIC_CORRELATIVE', 'Conectores correlativos', 'Coordinar elementos equivalentes con both/and, either/or, neither/nor y not only/but also.', 'B1', 2, true),
    ('20000000-0000-4000-8000-000000000035'::uuid, '10000000-0000-4000-8000-000000000007'::uuid, 'LOGIC_NEGATION', 'Negación y alcance', 'Controlar dobles negaciones, palabras de polaridad y el alcance lógico de la negación.', 'B1', 3, true)
