insert into public.grammar_exercises (
    id, primary_skill_id, format, cefr_band, difficulty, prompt,
    correct_option_id, corrected_sentence, explanation_es, status,
    content_version, source_note, linguistic_reviewed, fairness_reviewed
)
values
    ('30000000-0000-4000-8000-000000000001'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'sentence_completion', 'A2', 1, '{"kind":"sentence_completion","before":"The new laboratory ","after":" near the engineering building.","options":[{"id":"A","text":"is located"},{"id":"B","text":"locating","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las otras formas dejan la oración sin verbo principal o sustituyen el verbo por un sustantivo."},{"id":"C","text":"which located","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las otras formas dejan la oración sin verbo principal o sustituyen el verbo por un sustantivo."},{"id":"D","text":"location","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las otras formas dejan la oración sin verbo principal o sustituyen el verbo por un sustantivo."}]}'::jsonb, 'A', 'The new laboratory is located near the engineering building.', 'Una oración completa necesita un verbo finito; «is located» aporta verbo y completa el predicado.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000002'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'sentence_completion', 'A2', 2, '{"kind":"sentence_completion","before":"Several rare manuscripts ","after":" during the library renovation.","options":[{"id":"A","text":"were discovered"},{"id":"B","text":"discovering","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Un participio o una cláusula relativa aislada no puede funcionar como predicado principal."},{"id":"C","text":"that discovered","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Un participio o una cláusula relativa aislada no puede funcionar como predicado principal."},{"id":"D","text":"the discovery","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Un participio o una cláusula relativa aislada no puede funcionar como predicado principal."}]}'::jsonb, 'A', 'Several rare manuscripts were discovered during the library renovation.', 'El sujeto plural «manuscripts» requiere un verbo finito; la pasiva «were discovered» forma una oración completa.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000003'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'sentence_completion', 'A2', 3, '{"kind":"sentence_completion","before":"The committee''s final recommendation ","after":" after three hours of debate.","options":[{"id":"A","text":"surprised the audience"},{"id":"B","text":"surprising the audience","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las formas no finitas y los grupos nominales crean fragmentos cuando no hay otro verbo principal."},{"id":"C","text":"which surprised the audience","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las formas no finitas y los grupos nominales crean fragmentos cuando no hay otro verbo principal."},{"id":"D","text":"the audience''s surprise","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las formas no finitas y los grupos nominales crean fragmentos cuando no hay otro verbo principal."}]}'::jsonb, 'A', 'The committee''s final recommendation surprised the audience after three hours of debate.', '«Surprised» es el verbo principal en pasado y convierte el grupo nominal inicial en una oración completa.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000004'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'sentence_completion', 'A2', 1, '{"kind":"sentence_completion","before":"What the researchers found ","after":" the original hypothesis.","options":[{"id":"A","text":"contradicted"},{"id":"B","text":"contradicting","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Aunque el sujeto sea una cláusula, el predicado aún necesita un verbo conjugado."},{"id":"C","text":"a contradiction of","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Aunque el sujeto sea una cláusula, el predicado aún necesita un verbo conjugado."},{"id":"D","text":"which contradicted","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Aunque el sujeto sea una cláusula, el predicado aún necesita un verbo conjugado."}]}'::jsonb, 'A', 'What the researchers found contradicted the original hypothesis.', 'La cláusula nominal funciona como sujeto y necesita el verbo finito «contradicted» para completar la oración.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000005'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'error_identification', 'A2', 2, '{"kind":"error_identification","segments":[{"text":"The annual report containing detailed charts ","optionId":"A"},{"text":"and was ","optionId":"B"},{"text":"distributed to ","optionId":"C"},{"text":"every department.","optionId":"D"}]}'::jsonb, 'A', 'The annual report contained detailed charts and was distributed to every department.', 'Dos predicados coordinados deben compartir una forma finita; «containing» debe cambiar a «contained».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000006'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'error_identification', 'A2', 3, '{"kind":"error_identification","segments":[{"text":"Because the roads were icy, the morning buses ","optionId":"A"},{"text":"arriving at the station ","optionId":"B"},{"text":"more than an ","optionId":"C"},{"text":"hour late.","optionId":"D"}]}'::jsonb, 'B', 'Because the roads were icy, the morning buses arrived at the station more than an hour late.', 'La cláusula principal carece de verbo finito; «arriving» debe ser «arrived».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000007'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'error_identification', 'A2', 1, '{"kind":"error_identification","segments":[{"text":"The fossils discovered in the ","optionId":"A"},{"text":"valley provide important evidence ","optionId":"B"},{"text":"about a species that ","optionId":"C"},{"text":"once living there.","optionId":"D"}]}'::jsonb, 'D', 'The fossils discovered in the valley provide important evidence about a species that once lived there.', 'Después del sujeto relativo «that» se necesita el verbo finito «lived», no el participio «living».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000008'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'error_identification', 'A2', 2, '{"kind":"error_identification","segments":[{"text":"How the ","optionId":"A"},{"text":"device operates ","optionId":"B"},{"text":"still a mystery ","optionId":"C"},{"text":"to many engineers working on the project.","optionId":"D"}]}'::jsonb, 'C', 'How the device operates is still a mystery to many engineers working on the project.', 'La cláusula nominal inicial es el sujeto y necesita la cópula «is» antes del complemento.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000009'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'error_identification', 'A2', 3, '{"kind":"error_identification","segments":[{"text":"The lecture on marine ecosystems, which lasted nearly two hours, it attracted ","optionId":"A"},{"text":"a ","optionId":"B"},{"text":"large ","optionId":"C"},{"text":"audience.","optionId":"D"}]}'::jsonb, 'A', 'The lecture on marine ecosystems, which lasted nearly two hours, attracted a large audience.', 'El sujeto ya es «the lecture»; el pronombre «it» crea un doble sujeto y debe eliminarse.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000010'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'error_identification', 'A2', 1, '{"kind":"error_identification","segments":[{"text":"A collection of early photographs from the northern provinces ","optionId":"A"},{"text":"on display ","optionId":"B"},{"text":"in the ","optionId":"C"},{"text":"main gallery.","optionId":"D"}]}'::jsonb, 'B', 'A collection of early photographs from the northern provinces is on display in the main gallery.', 'El grupo nominal necesita la cópula «is» para formar una oración completa.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000011'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'sentence_completion', 'A2', 2, '{"kind":"sentence_completion","before":"The guide explained ","after":" to the visitors.","options":[{"id":"A","text":"the safety rules clearly"},{"id":"B","text":"clearly the safety rules","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"En inglés el adverbio no debe separar el determinante de su sustantivo ni introducir el objeto con «to»."},{"id":"C","text":"the clearly safety rules","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"En inglés el adverbio no debe separar el determinante de su sustantivo ni introducir el objeto con «to»."},{"id":"D","text":"to clearly the safety rules","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"En inglés el adverbio no debe separar el determinante de su sustantivo ni introducir el objeto con «to»."}]}'::jsonb, 'A', 'The guide explained the safety rules clearly to the visitors.', 'El objeto directo «the safety rules» sigue al verbo y el adverbio de modo puede colocarse después del objeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000012'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'sentence_completion', 'A2', 3, '{"kind":"sentence_completion","before":"The astronomers ","after":" from the desert observatory.","options":[{"id":"A","text":"carefully recorded the signal"},{"id":"B","text":"recorded carefully the signal","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Mover el objeto antes del verbo sin una construcción especial produce un orden no canónico."},{"id":"C","text":"the signal carefully recorded","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Mover el objeto antes del verbo sin una construcción especial produce un orden no canónico."},{"id":"D","text":"carefully the signal recorded","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Mover el objeto antes del verbo sin una construcción especial produce un orden no canónico."}]}'::jsonb, 'A', 'The astronomers carefully recorded the signal from the desert observatory.', 'Un adverbio de modo puede aparecer antes del verbo léxico; el orden básico sigue siendo sujeto–verbo–objeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000013'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'sentence_completion', 'A2', 1, '{"kind":"sentence_completion","before":"Only after the inspection ","after":" the building.","options":[{"id":"A","text":"did the workers enter"},{"id":"B","text":"the workers entered","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La inversión requiere «did» seguido de sujeto y verbo en forma base."},{"id":"C","text":"entered the workers","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La inversión requiere «did» seguido de sujeto y verbo en forma base."},{"id":"D","text":"the workers did enter","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La inversión requiere «did» seguido de sujeto y verbo en forma base."}]}'::jsonb, 'A', 'Only after the inspection did the workers enter the building.', 'Una expresión negativa o restrictiva inicial como «only after» exige inversión auxiliar–sujeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000014'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'sentence_completion', 'A2', 2, '{"kind":"sentence_completion","before":"The professor asked ","after":" before Friday.","options":[{"id":"A","text":"the students to submit their drafts"},{"id":"B","text":"to submit the students their drafts","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Los complementos no pueden desplazarse libremente sin alterar la estructura verbal."},{"id":"C","text":"their drafts the students to submit","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Los complementos no pueden desplazarse libremente sin alterar la estructura verbal."},{"id":"D","text":"the students their drafts submit","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Los complementos no pueden desplazarse libremente sin alterar la estructura verbal."}]}'::jsonb, 'A', 'The professor asked the students to submit their drafts before Friday.', 'Con «ask», el orden es verbo + persona + infinitivo con «to» + objeto del infinitivo.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000015'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'error_identification', 'A2', 3, '{"kind":"error_identification","segments":[{"text":"The ","optionId":"A"},{"text":"technician ","optionId":"B"},{"text":"installed carefully ","optionId":"C"},{"text":"the new sensor inside the chamber.","optionId":"D"}]}'::jsonb, 'C', 'The technician carefully installed the new sensor inside the chamber.', 'Con un objeto relativamente largo, el adverbio de modo se coloca naturalmente antes del verbo o después del objeto, no entre verbo y objeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000016'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'error_identification', 'A2', 1, '{"kind":"error_identification","segments":[{"text":"The ","optionId":"A"},{"text":"research ","optionId":"B"},{"text":"team ","optionId":"C"},{"text":"every morning checks the temperature of the storage room.","optionId":"D"}]}'::jsonb, 'D', 'The research team checks the temperature of the storage room every morning.', 'Los adverbios de frecuencia definida suelen ir al final; no deben interrumpir el orden sujeto–verbo de este modo.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000017'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'error_identification', 'A2', 2, '{"kind":"error_identification","segments":[{"text":"The museum displayed in the central hall ","optionId":"A"},{"text":"a sculpture ","optionId":"B"},{"text":"made of ","optionId":"C"},{"text":"recycled glass.","optionId":"D"}]}'::jsonb, 'A', 'The museum displayed a sculpture made of recycled glass in the central hall.', 'El objeto directo debe seguir al verbo antes del complemento de lugar cuando no hay razón discursiva para invertirlos.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000018'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'error_identification', 'A2', 3, '{"kind":"error_identification","segments":[{"text":"The students wanted to know ","optionId":"A"},{"text":"why had the experiment failed ","optionId":"B"},{"text":"despite the careful planning ","optionId":"C"},{"text":"of the research team.","optionId":"D"}]}'::jsonb, 'B', 'The students wanted to know why the experiment had failed despite the careful planning of the research team.', 'Las preguntas indirectas conservan el orden declarativo sujeto–auxiliar: «why the experiment had failed».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000019'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'error_identification', 'A2', 1, '{"kind":"error_identification","segments":[{"text":"The ","optionId":"A"},{"text":"editor ","optionId":"B"},{"text":"sent yesterday ","optionId":"C"},{"text":"the revised manuscript to the publisher.","optionId":"D"}]}'::jsonb, 'C', 'The editor sent the revised manuscript to the publisher yesterday.', 'El adverbio de tiempo definido suele ir al final y no debe separar el verbo transitivo de su objeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000020'::uuid, '20000000-0000-4000-8000-000000000002'::uuid, 'error_identification', 'A2', 2, '{"kind":"error_identification","segments":[{"text":"The ","optionId":"A"},{"text":"documentary ","optionId":"B"},{"text":"shows ","optionId":"C"},{"text":"how do coastal communities adapt to seasonal flooding and rising tides.","optionId":"D"}]}'::jsonb, 'D', 'The documentary shows how coastal communities adapt to seasonal flooding and rising tides.', 'Después de «how» en una cláusula subordinada se usa orden declarativo, no inversión de pregunta.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000021'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'sentence_completion', 'B1', 3, '{"kind":"sentence_completion","before":"","after":" several possible explanations for the sudden decline.","options":[{"id":"A","text":"There are"},{"id":"B","text":"It is","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«It» no introduce una lista existente y «there is» no concuerda con un sustantivo plural."},{"id":"C","text":"There is","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«It» no introduce una lista existente y «there is» no concuerda con un sustantivo plural."},{"id":"D","text":"They are","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«It» no introduce una lista existente y «there is» no concuerda con un sustantivo plural."}]}'::jsonb, 'A', 'There are several possible explanations for the sudden decline.', '«There» introduce existencia y el verbo concuerda con el sustantivo plural «explanations».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000022'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'sentence_completion', 'B1', 1, '{"kind":"sentence_completion","before":"","after":" essential to calibrate the instrument before each use.","options":[{"id":"A","text":"It is"},{"id":"B","text":"There is","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La construcción existencial con «there» no puede introducir directamente un adjetivo seguido de infinitivo."},{"id":"C","text":"It has","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La construcción existencial con «there» no puede introducir directamente un adjetivo seguido de infinitivo."},{"id":"D","text":"There are","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La construcción existencial con «there» no puede introducir directamente un adjetivo seguido de infinitivo."}]}'::jsonb, 'A', 'It is essential to calibrate the instrument before each use.', '«It» funciona como sujeto formal antes del adjetivo y desplaza el infinitivo al final.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000023'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'sentence_completion', 'B1', 2, '{"kind":"sentence_completion","before":"","after":" no evidence that the species migrated during winter.","options":[{"id":"A","text":"There is"},{"id":"B","text":"It is","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Evidence» no admite concordancia plural y «it» cambiaría la estructura."},{"id":"C","text":"There are","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Evidence» no admite concordancia plural y «it» cambiaría la estructura."},{"id":"D","text":"It has","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Evidence» no admite concordancia plural y «it» cambiaría la estructura."}]}'::jsonb, 'A', 'There is no evidence that the species migrated during winter.', 'La estructura existencial usa «there is» porque «evidence» es incontable y singular gramaticalmente.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000024'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'sentence_completion', 'B1', 3, '{"kind":"sentence_completion","before":"","after":" surprising that the two samples produced identical results.","options":[{"id":"A","text":"It was"},{"id":"B","text":"There was","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La construcción necesita el sujeto formal «it» antes del adjetivo evaluativo."},{"id":"C","text":"That was","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La construcción necesita el sujeto formal «it» antes del adjetivo evaluativo."},{"id":"D","text":"What was","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La construcción necesita el sujeto formal «it» antes del adjetivo evaluativo."}]}'::jsonb, 'A', 'It was surprising that the two samples produced identical results.', '«It» anticipatorio ocupa la posición de sujeto y la cláusula con «that» expresa el contenido real.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000025'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"There was ","optionId":"A"},{"text":"many objections to ","optionId":"B"},{"text":"the proposed schedule ","optionId":"C"},{"text":"at yesterday''s meeting.","optionId":"D"}]}'::jsonb, 'A', 'There were many objections to the proposed schedule at yesterday''s meeting.', 'En una construcción existencial, el verbo concuerda con el grupo nominal plural «many objections».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000026'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'error_identification', 'B1', 2, '{"kind":"error_identification","segments":[{"text":"It are ","optionId":"A"},{"text":"unlikely that the glacier ","optionId":"B"},{"text":"will recover completely ","optionId":"C"},{"text":"within a decade.","optionId":"D"}]}'::jsonb, 'A', 'It is unlikely that the glacier will recover completely within a decade.', 'El sujeto formal singular «it» requiere la forma singular «is».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000027'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'error_identification', 'B1', 3, '{"kind":"error_identification","segments":[{"text":"There appear to be ","optionId":"A"},{"text":"a significant difference between ","optionId":"B"},{"text":"the two methods used ","optionId":"C"},{"text":"in the survey.","optionId":"D"}]}'::jsonb, 'A', 'There appears to be a significant difference between the two methods used in the survey.', 'El verbo «appears» concuerda con el sujeto lógico singular «a significant difference».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000028'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"There is ","optionId":"A"},{"text":"several reasons why ","optionId":"B"},{"text":"the archive closed ","optionId":"C"},{"text":"early today.","optionId":"D"}]}'::jsonb, 'A', 'There are several reasons why the archive closed early today.', 'El sustantivo plural «reasons» exige «there are».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000029'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'error_identification', 'B1', 2, '{"kind":"error_identification","segments":[{"text":"It seems that ","optionId":"A"},{"text":"the new policy ","optionId":"B"},{"text":"has reduced delays ","optionId":"C"},{"text":"is encouraging.","optionId":"D"}]}'::jsonb, 'A', 'That the new policy has reduced delays is encouraging.', 'La oración mezcla «it seems that» con otra cópula; la cláusula con «that» debe funcionar directamente como sujeto de «is encouraging».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000030'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'error_identification', 'B1', 3, '{"kind":"error_identification","segments":[{"text":"There remains ","optionId":"A"},{"text":"two unresolved questions about ","optionId":"B"},{"text":"the origin of ","optionId":"C"},{"text":"the stone tools.","optionId":"D"}]}'::jsonb, 'A', 'There remain two unresolved questions about the origin of the stone tools.', 'Con «there» existencial, «remain» concuerda con el sujeto lógico plural «two questions».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000031'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'sentence_completion', 'B2', 1, '{"kind":"sentence_completion","before":"Rarely ","after":" such a well-preserved fossil before.","options":[{"id":"A","text":"have scientists found"},{"id":"B","text":"scientists have found","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La inversión usa auxiliar + sujeto + participio; después de «did» iría la forma base."},{"id":"C","text":"scientists found","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La inversión usa auxiliar + sujeto + participio; después de «did» iría la forma base."},{"id":"D","text":"did scientists found","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La inversión usa auxiliar + sujeto + participio; después de «did» iría la forma base."}]}'::jsonb, 'A', 'Rarely have scientists found such a well-preserved fossil before.', 'El adverbio negativo inicial «rarely» exige inversión entre auxiliar y sujeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000032'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'sentence_completion', 'B2', 2, '{"kind":"sentence_completion","before":"Not until the lights went out ","after":" the wiring problem.","options":[{"id":"A","text":"did the staff notice"},{"id":"B","text":"the staff noticed","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La cláusula temporal no se invierte; la inversión ocurre en el resultado principal."},{"id":"C","text":"had the staff noticed","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La cláusula temporal no se invierte; la inversión ocurre en el resultado principal."},{"id":"D","text":"the staff did notice","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La cláusula temporal no se invierte; la inversión ocurre en el resultado principal."}]}'::jsonb, 'A', 'Not until the lights went out did the staff notice the wiring problem.', '«Not until» al inicio activa inversión en la cláusula principal: «did + sujeto + verbo base».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000033'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'sentence_completion', 'B2', 3, '{"kind":"sentence_completion","before":"Had the warning arrived earlier, ","after":" enough time to evacuate.","options":[{"id":"A","text":"would the residents have had","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La cláusula de resultado mantiene orden normal y usa «would have + participio»."},{"id":"B","text":"the residents would have had"},{"id":"C","text":"the residents had","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La cláusula de resultado mantiene orden normal y usa «would have + participio»."},{"id":"D","text":"the residents will have","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La cláusula de resultado mantiene orden normal y usa «would have + participio»."}]}'::jsonb, 'B', 'Had the warning arrived earlier, the residents would have had enough time to evacuate.', 'La inversión «Had + sujeto + participio» sustituye a «if» en una condicional pasada.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000034'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'sentence_completion', 'B2', 1, '{"kind":"sentence_completion","before":"Only by comparing both samples ","after":" the contamination.","options":[{"id":"A","text":"we can detect","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El modal debe preceder al sujeto, y el verbo léxico permanece en forma base."},{"id":"B","text":"can we detect"},{"id":"C","text":"we detect can","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El modal debe preceder al sujeto, y el verbo léxico permanece en forma base."},{"id":"D","text":"can detect we","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El modal debe preceder al sujeto, y el verbo léxico permanece en forma base."}]}'::jsonb, 'B', 'Only by comparing both samples can we detect the contamination.', '«Only by» al inicio exige inversión del modal «can» y el sujeto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000035'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'error_identification', 'B2', 2, '{"kind":"error_identification","segments":[{"text":"Never before ","optionId":"A"},{"text":"researchers observed ","optionId":"B"},{"text":"such rapid changes in ","optionId":"C"},{"text":"the upper atmosphere.","optionId":"D"}]}'::jsonb, 'B', 'Never before have researchers observed such rapid changes in the upper atmosphere.', 'La expresión negativa inicial requiere inversión con el auxiliar perfecto «have».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000036'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'error_identification', 'B2', 3, '{"kind":"error_identification","segments":[{"text":"Only after the ","optionId":"A"},{"text":"samples cooled ","optionId":"B"},{"text":"the technician could ","optionId":"C"},{"text":"measure their density with reasonable accuracy.","optionId":"D"}]}'::jsonb, 'C', 'Only after the samples cooled could the technician measure their density with reasonable accuracy.', '«Only after» exige que el modal aparezca antes del sujeto en la cláusula principal.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000037'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'error_identification', 'B2', 1, '{"kind":"error_identification","segments":[{"text":"No sooner ","optionId":"A"},{"text":"had the ","optionId":"B"},{"text":"lecture begun ","optionId":"C"},{"text":"when the fire alarm forced everyone to leave the hall.","optionId":"D"}]}'::jsonb, 'D', 'No sooner had the lecture begun than the fire alarm forced everyone to leave the hall.', 'La correlación fija es «no sooner ... than», no «when».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000038'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'error_identification', 'B2', 2, '{"kind":"error_identification","segments":[{"text":"Should the weather improves ","optionId":"A"},{"text":"the field team ","optionId":"B"},{"text":"will resume work ","optionId":"C"},{"text":"at sunrise.","optionId":"D"}]}'::jsonb, 'A', 'Should the weather improve, the field team will resume work at sunrise.', 'En la condicional invertida con «should», el verbo siguiente debe ir en forma base: «improve».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000039'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'error_identification', 'B2', 3, '{"kind":"error_identification","segments":[{"text":"Seldom the river rises ","optionId":"A"},{"text":"above this level before ","optionId":"B"},{"text":"the beginning of ","optionId":"C"},{"text":"the rainy season.","optionId":"D"}]}'::jsonb, 'A', 'Seldom does the river rise above this level before the beginning of the rainy season.', '«Seldom» inicial requiere «does + sujeto + verbo base».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000040'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, 'error_identification', 'B2', 1, '{"kind":"error_identification","segments":[{"text":"Under no circumstances ","optionId":"A"},{"text":"visitors should touch ","optionId":"B"},{"text":"the fragile textiles displayed ","optionId":"C"},{"text":"in this room.","optionId":"D"}]}'::jsonb, 'B', 'Under no circumstances should visitors touch the fragile textiles displayed in this room.', 'La frase negativa inicial obliga a invertir el modal y el sujeto: «should visitors».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000041'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'sentence_completion', 'B1', 2, '{"kind":"sentence_completion","before":"The first trial failed; ","after":", the team adjusted the temperature.","options":[{"id":"A","text":"because","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las conjunciones subordinantes necesitarían integrarse en una sola estructura, no seguir a un punto y coma así."},{"id":"B","text":"therefore"},{"id":"C","text":"although","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las conjunciones subordinantes necesitarían integrarse en una sola estructura, no seguir a un punto y coma así."},{"id":"D","text":"so that","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Las conjunciones subordinantes necesitarían integrarse en una sola estructura, no seguir a un punto y coma así."}]}'::jsonb, 'B', 'The first trial failed; therefore, the team adjusted the temperature.', 'Un adverbio conjuntivo como «therefore» puede unir dos oraciones independientes después de punto y coma.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000042'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'sentence_completion', 'B1', 3, '{"kind":"sentence_completion","before":"","after":" the road was flooded, the delivery arrived on time.","options":[{"id":"A","text":"Despite","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Despite» necesita un sustantivo o gerundio; los adverbios conjuntivos requieren otra puntuación."},{"id":"B","text":"Although"},{"id":"C","text":"However","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Despite» necesita un sustantivo o gerundio; los adverbios conjuntivos requieren otra puntuación."},{"id":"D","text":"Therefore","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Despite» necesita un sustantivo o gerundio; los adverbios conjuntivos requieren otra puntuación."}]}'::jsonb, 'B', 'Although the road was flooded, the delivery arrived on time.', '«Although» introduce una cláusula concesiva completa con sujeto y verbo.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000043'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'sentence_completion', 'B1', 1, '{"kind":"sentence_completion","before":"The survey was repeated ","after":" the original sample was too small.","options":[{"id":"A","text":"because of","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Because of» y «despite» exigen grupos nominales, mientras «however» no subordina."},{"id":"B","text":"because"},{"id":"C","text":"despite","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Because of» y «despite» exigen grupos nominales, mientras «however» no subordina."},{"id":"D","text":"however","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Because of» y «despite» exigen grupos nominales, mientras «however» no subordina."}]}'::jsonb, 'B', 'The survey was repeated because the original sample was too small.', '«Because» introduce una cláusula con sujeto y verbo y expresa la causa.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000044'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'sentence_completion', 'B1', 2, '{"kind":"sentence_completion","before":"The device is inexpensive, ","after":" it performs as reliably as larger models.","options":[{"id":"A","text":"because of","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Un adverbio conjuntivo como «therefore» no puede seguir solo a una coma entre dos oraciones."},{"id":"B","text":"yet"},{"id":"C","text":"unless","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Un adverbio conjuntivo como «therefore» no puede seguir solo a una coma entre dos oraciones."},{"id":"D","text":"therefore","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Un adverbio conjuntivo como «therefore» no puede seguir solo a una coma entre dos oraciones."}]}'::jsonb, 'B', 'The device is inexpensive, yet it performs as reliably as larger models.', 'La conjunción coordinante «yet» conecta dos cláusulas independientes y marca contraste.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000045'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'error_identification', 'B1', 3, '{"kind":"error_identification","segments":[{"text":"The storm ended before dawn, ","optionId":"A"},{"text":"the field crew ","optionId":"B"},{"text":"began its inspection ","optionId":"C"},{"text":"at seven o''clock.","optionId":"D"}]}'::jsonb, 'A', 'The storm ended before dawn, and the field crew began its inspection at seven o''clock.', 'Dos cláusulas independientes no deben unirse solo con coma; hace falta una conjunción o un punto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000046'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"Because the ","optionId":"A"},{"text":"original map ","optionId":"B"},{"text":"was drawn without accurate instruments. ","optionId":"C"},{"text":"The distances between villages are only approximate.","optionId":"D"}]}'::jsonb, 'C', 'Because the original map was drawn without accurate instruments, the distances between villages are only approximate.', 'La cláusula con «because» no debe cerrarse como fragmento; se une a la cláusula principal con coma.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000047'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'error_identification', 'B1', 2, '{"kind":"error_identification","segments":[{"text":"The water level dropped rapidly ","optionId":"A"},{"text":"however, the bridge ","optionId":"B"},{"text":"remained closed for ","optionId":"C"},{"text":"another day.","optionId":"D"}]}'::jsonb, 'A', 'The water level dropped rapidly; however, the bridge remained closed for another day.', 'Antes de «however» entre dos cláusulas independientes se necesita punto y coma o punto.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000048'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'error_identification', 'B1', 3, '{"kind":"error_identification","segments":[{"text":"Although the ","optionId":"A"},{"text":"treatment was ","optionId":"B"},{"text":"expensive, ","optionId":"C"},{"text":"but it produced better results than the previous method.","optionId":"D"}]}'::jsonb, 'D', 'Although the treatment was expensive, it produced better results than the previous method.', '«Although» ya marca la subordinación; añadir «but» duplica el conector.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000049'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"The archive reopened in ","optionId":"A"},{"text":"May, after being closed ","optionId":"B"},{"text":"for structural repairs ","optionId":"C"},{"text":"since nearly a year.","optionId":"D"}]}'::jsonb, 'D', 'The archive reopened in May, after being closed for structural repairs for nearly a year.', 'Una duración completa usa «for», no «since»; la coma puede conservarse si el complemento se presenta como información adicional.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000050'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, 'error_identification', 'B1', 2, '{"kind":"error_identification","segments":[{"text":"The samples must remain frozen ","optionId":"A"},{"text":"otherwise they may deteriorate ","optionId":"B"},{"text":"before the laboratory ","optionId":"C"},{"text":"can analyze them.","optionId":"D"}]}'::jsonb, 'A', 'The samples must remain frozen; otherwise, they may deteriorate before the laboratory can analyze them.', '«Otherwise» conecta dos cláusulas independientes y necesita punto y coma o punto antes.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
