    ('30000000-0000-4000-8000-000000000259'::uuid, '20000000-0000-4000-8000-000000000026'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"The article presents ","optionId":"A"},{"text":"a detailed unusually analysis ","optionId":"B"},{"text":"of population changes ","optionId":"C"},{"text":"over three centuries.","optionId":"D"}]}'::jsonb, 'B', 'The article presents an unusually detailed analysis of population changes over three centuries.', 'El adverbio «unusually» debe preceder al adjetivo «detailed», y la frase comienza con «an».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
