    ('30000000-0000-4000-8000-000000000261'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'sentence_completion', 'A2', 3, '{"kind":"sentence_completion","before":"The revised procedure is ","after":" the original one.","options":[{"id":"A","text":"more efficient that","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"No se combina «most» con «than» ni se añade «-er» a este adjetivo."},{"id":"B","text":"most efficient than","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"No se combina «most» con «than» ni se añade «-er» a este adjetivo."},{"id":"C","text":"efficienter than","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"No se combina «most» con «than» ni se añade «-er» a este adjetivo."},{"id":"D","text":"more efficient than"}]}'::jsonb, 'D', 'The revised procedure is more efficient than the original one.', 'Los adjetivos largos forman el comparativo con «more» y usan «than».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000262'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'sentence_completion', 'A2', 1, '{"kind":"sentence_completion","before":"Of all the samples, this one contains ","after":" concentration of salt.","options":[{"id":"A","text":"the higher","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El comparativo «higher» requeriría dos términos explícitos."},{"id":"B","text":"higher than","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El comparativo «higher» requeriría dos términos explícitos."},{"id":"C","text":"most high","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El comparativo «higher» requeriría dos términos explícitos."},{"id":"D","text":"the highest"}]}'::jsonb, 'D', 'Of all the samples, this one contains the highest concentration of salt.', 'Al comparar un elemento con todo un grupo se usa el superlativo con «the».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000263'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'sentence_completion', 'A2', 2, '{"kind":"sentence_completion","before":"The more carefully the data are checked, ","after":" the final report will be.","options":[{"id":"A","text":"more reliable","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Ambas mitades requieren «the» para expresar la relación gradual."},{"id":"B","text":"the most reliable","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Ambas mitades requieren «the» para expresar la relación gradual."},{"id":"C","text":"reliabler","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Ambas mitades requieren «the» para expresar la relación gradual."},{"id":"D","text":"the more reliable"}]}'::jsonb, 'D', 'The more carefully the data are checked, the more reliable the final report will be.', 'La estructura proporcional es «the more ..., the more ...».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000264'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'sentence_completion', 'A2', 3, '{"kind":"sentence_completion","before":"The northern route is not ","after":" the coastal route.","options":[{"id":"A","text":"so direct than","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"No se mezcla «as» con «than»."},{"id":"B","text":"as direct than","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"No se mezcla «as» con «than»."},{"id":"C","text":"more direct as","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"No se mezcla «as» con «than»."},{"id":"D","text":"as direct as"}]}'::jsonb, 'D', 'The northern route is not as direct as the coastal route.', 'La comparación de igualdad usa «as + adjetivo + as».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000265'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'error_identification', 'A2', 1, '{"kind":"error_identification","segments":[{"text":"This ","optionId":"A"},{"text":"microscope ","optionId":"B"},{"text":"is ","optionId":"C"},{"text":"more powerful that the model used in the older laboratory.","optionId":"D"}]}'::jsonb, 'D', 'This microscope is more powerful than the model used in the older laboratory.', 'Los comparativos usan «than», no «that».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000266'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'error_identification', 'A2', 2, '{"kind":"error_identification","segments":[{"text":"The second experiment produced ","optionId":"A"},{"text":"the most consistent results ","optionId":"B"},{"text":"than the first ","optionId":"C"},{"text":"under identical conditions.","optionId":"D"}]}'::jsonb, 'B', 'The second experiment produced more consistent results than the first under identical conditions.', 'Una comparación entre dos elementos usa comparativo, no superlativo.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000267'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'error_identification', 'A2', 3, '{"kind":"error_identification","segments":[{"text":"The river ","optionId":"A"},{"text":"is ","optionId":"B"},{"text":"twice longer than ","optionId":"C"},{"text":"it was before the map was revised.","optionId":"D"}]}'::jsonb, 'C', 'The river is twice as long as it was before the map was revised.', 'Con multiplicadores como «twice» se usa «as + adjetivo + as».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000268'::uuid, '20000000-0000-4000-8000-000000000027'::uuid, 'error_identification', 'A2', 1, '{"kind":"error_identification","segments":[{"text":"Of the ","optionId":"A"},{"text":"two ","optionId":"B"},{"text":"proposals, ","optionId":"C"},{"text":"the first is the best suited to the needs of a small community.","optionId":"D"}]}'::jsonb, 'D', 'Of the two proposals, the first is better suited to the needs of a small community.', 'Entre dos alternativas se usa el comparativo «better», no el superlativo «best».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
