    ('30000000-0000-4000-8000-000000000322'::uuid, '20000000-0000-4000-8000-000000000033'::uuid, 'sentence_completion', 'B1', 1, '{"kind":"sentence_completion","before":"The new system is faster, safer, and ","after":" than the previous one.","options":[{"id":"A","text":"reliably","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La tercera forma debe mantener función adjetival y grado comparativo."},{"id":"B","text":"most reliable","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La tercera forma debe mantener función adjetival y grado comparativo."},{"id":"C","text":"reliability","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"La tercera forma debe mantener función adjetival y grado comparativo."},{"id":"D","text":"more reliable"}]}'::jsonb, 'D', 'The new system is faster, safer, and more reliable than the previous one.', 'La lista coordina tres adjetivos comparativos que describen al sistema.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
