    ('30000000-0000-4000-8000-000000000324'::uuid, '20000000-0000-4000-8000-000000000033'::uuid, 'sentence_completion', 'B1', 3, '{"kind":"sentence_completion","before":"The professor asked students to read the article and ","after":" its main argument.","options":[{"id":"A","text":"summarizing","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Ambos elementos deben ser formas verbales base paralelas."},{"id":"B","text":"to summarized","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Ambos elementos deben ser formas verbales base paralelas."},{"id":"C","text":"summary","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"Ambos elementos deben ser formas verbales base paralelas."},{"id":"D","text":"summarize"}]}'::jsonb, 'D', 'The professor asked students to read the article and summarize its main argument.', 'Los verbos coordinados comparten el «to»: «to read and summarize».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
