    ('30000000-0000-4000-8000-000000000331'::uuid, '20000000-0000-4000-8000-000000000034'::uuid, 'sentence_completion', 'B1', 1, '{"kind":"sentence_completion","before":"The treatment is ","after":" inexpensive and easy to administer.","options":[{"id":"A","text":"either","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Either» necesitaría «or» y «neither» expresaría negación."},{"id":"B","text":"neither","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Either» necesitaría «or» y «neither» expresaría negación."},{"id":"C","text":"not","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«Either» necesitaría «or» y «neither» expresaría negación."},{"id":"D","text":"both"}]}'::jsonb, 'D', 'The treatment is both inexpensive and easy to administer.', '«Both ... and» suma dos características verdaderas.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
