    ('30000000-0000-4000-8000-000000000333'::uuid, '20000000-0000-4000-8000-000000000034'::uuid, 'sentence_completion', 'B1', 3, '{"kind":"sentence_completion","before":"","after":" the director nor the assistants were available.","options":[{"id":"A","text":"Either","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El verbo concuerda aquí con el elemento cercano plural «assistants»."},{"id":"B","text":"Both","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El verbo concuerda aquí con el elemento cercano plural «assistants»."},{"id":"C","text":"Not only","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El verbo concuerda aquí con el elemento cercano plural «assistants»."},{"id":"D","text":"Neither"}]}'::jsonb, 'D', 'Neither the director nor the assistants were available.', '«Neither ... nor» niega ambas alternativas.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000334'::uuid, '20000000-0000-4000-8000-000000000034'::uuid, 'sentence_completion', 'B1', 1, '{"kind":"sentence_completion","before":"The new evidence not only confirms the date ","after":" identifies the original owner.","options":[{"id":"A","text":"and either","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El conector debe conservar la correlación completa."},{"id":"B","text":"nor","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El conector debe conservar la correlación completa."},{"id":"C","text":"as well","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"El conector debe conservar la correlación completa."},{"id":"D","text":"but also"}]}'::jsonb, 'D', 'The new evidence not only confirms the date but also identifies the original owner.', 'La pareja fija «not only ... but also» coordina dos verbos equivalentes.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
