    ('30000000-0000-4000-8000-000000000337'::uuid, '20000000-0000-4000-8000-000000000034'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"The instrument ","optionId":"A"},{"text":"can ","optionId":"B"},{"text":"measure ","optionId":"C"},{"text":"either temperature and air pressure at the same time.","optionId":"D"}]}'::jsonb, 'D', 'The instrument can measure both temperature and air pressure at the same time.', 'Si se incluyen las dos medidas simultáneamente, corresponde «both ... and», no «either».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
