    ('30000000-0000-4000-8000-000000000341'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'sentence_completion', 'B1', 2, '{"kind":"sentence_completion","before":"The researchers found ","after":" evidence of contamination in the control sample.","options":[{"id":"A","text":"not any of","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«None» no modifica directamente a un sustantivo y «nothing» ya es pronombre."},{"id":"B","text":"none","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«None» no modifica directamente a un sustantivo y «nothing» ya es pronombre."},{"id":"C","text":"nothing","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«None» no modifica directamente a un sustantivo y «nothing» ya es pronombre."},{"id":"D","text":"no"}]}'::jsonb, 'D', 'The researchers found no evidence of contamination in the control sample.', '«No» funciona como determinante antes del sustantivo incontable «evidence».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
