    ('30000000-0000-4000-8000-000000000344'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'sentence_completion', 'B1', 2, '{"kind":"sentence_completion","before":"","after":" of the samples showed any visible change.","options":[{"id":"A","text":"No","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«No» necesitaría ir directamente antes del sustantivo, sin «of»."},{"id":"B","text":"Nothing","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«No» necesitaría ir directamente antes del sustantivo, sin «of»."},{"id":"C","text":"Neither one of all","misconceptionCode":"FORM_OR_STRUCTURE","feedback":"«No» necesitaría ir directamente antes del sustantivo, sin «of»."},{"id":"D","text":"None"}]}'::jsonb, 'D', 'None of the samples showed any visible change.', '«None of + plural» funciona como sujeto y combina naturalmente con «any» en la cláusula negativa.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000345'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'error_identification', 'B1', 3, '{"kind":"error_identification","segments":[{"text":"The committee ","optionId":"A"},{"text":"did not ","optionId":"B"},{"text":"find ","optionId":"C"},{"text":"no reason to delay the launch after the final inspection.","optionId":"D"}]}'::jsonb, 'D', 'The committee did not find any reason to delay the launch after the final inspection.', 'El inglés estándar evita la doble negación «not ... no»; se usa «any».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000346'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"Hardly no information ","optionId":"A"},{"text":"was available about ","optionId":"B"},{"text":"the earliest phase ","optionId":"C"},{"text":"of the settlement.","optionId":"D"}]}'::jsonb, 'A', 'Hardly any information was available about the earliest phase of the settlement.', 'Después de «hardly» se usa «any», no otro negativo.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000347'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'error_identification', 'B1', 2, '{"kind":"error_identification","segments":[{"text":"The instrument is not ","optionId":"A"},{"text":"sensitive enough detecting ","optionId":"B"},{"text":"the smallest changes ","optionId":"C"},{"text":"in air pressure.","optionId":"D"}]}'::jsonb, 'B', 'The instrument is not sensitive enough to detect the smallest changes in air pressure.', 'La estructura es «adjective + enough + to-infinitive».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000348'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'error_identification', 'B1', 3, '{"kind":"error_identification","segments":[{"text":"Neither of ","optionId":"A"},{"text":"the witnesses ","optionId":"B"},{"text":"did not remember ","optionId":"C"},{"text":"the exact time when the alarm sounded.","optionId":"D"}]}'::jsonb, 'C', 'Neither of the witnesses remembered the exact time when the alarm sounded.', '«Neither» ya contiene negación; «did not» crea una doble negación.', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000349'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'error_identification', 'B1', 1, '{"kind":"error_identification","segments":[{"text":"The ","optionId":"A"},{"text":"results ","optionId":"B"},{"text":"are ","optionId":"C"},{"text":"too inconsistent that the researchers cannot draw a firm conclusion.","optionId":"D"}]}'::jsonb, 'D', 'The results are too inconsistent for the researchers to draw a firm conclusion.', 'La estructura de exceso es «too + adjective + for + noun + to-infinitive».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true),
    ('30000000-0000-4000-8000-000000000350'::uuid, '20000000-0000-4000-8000-000000000035'::uuid, 'error_identification', 'B1', 2, '{"kind":"error_identification","segments":[{"text":"The new treatment has scarcely any side effects, ","optionId":"A"},{"text":"and neither causes ","optionId":"B"},{"text":"significant ","optionId":"C"},{"text":"discomfort.","optionId":"D"}]}'::jsonb, 'B', 'The new treatment has scarcely any side effects and causes no significant discomfort.', '«Neither» necesita una pareja o dos alternativas; aquí la negación simple debe expresarse con «no».', 'published', 1, 'Contenido original Macitta; revisión lingüística y de fairness v1.', true, true)
on conflict (id) do update
set primary_skill_id = excluded.primary_skill_id,
    format = excluded.format,
    cefr_band = excluded.cefr_band,
    difficulty = excluded.difficulty,
    prompt = excluded.prompt,
    correct_option_id = excluded.correct_option_id,
    corrected_sentence = excluded.corrected_sentence,
    explanation_es = excluded.explanation_es,
    status = excluded.status,
    content_version = excluded.content_version,
    source_note = excluded.source_note,
    linguistic_reviewed = excluded.linguistic_reviewed,
    fairness_reviewed = excluded.fairness_reviewed,
    updated_at = now();

do $catalog_assertions$
declare
    domain_count integer;
    skill_count integer;
    exercise_count integer;
    invalid_count integer;
begin
    select count(*) into domain_count from public.grammar_domains;
    select count(*) into skill_count from public.grammar_skills where is_active;
    select count(*) into exercise_count from public.grammar_exercises where status = 'published' and content_version = 1;
    select count(*) into invalid_count
    from public.grammar_exercises
    where status = 'published'
      and (
          not linguistic_reviewed
          or not fairness_reviewed
          or correct_option_id not in ('A', 'B', 'C', 'D')
      );

    if domain_count < 7 or skill_count < 35 or exercise_count < 350 or invalid_count <> 0 then
        raise exception 'Grammar catalog assertion failed: domains %, skills %, exercises %, invalid %',
            domain_count, skill_count, exercise_count, invalid_count;
    end if;
end;
$catalog_assertions$;

commit;
